    if re.search(r'thuế|thue|hóa đơn|hoa don|gtgt|tncn|tndn|môn bài|nhà thầu|mã số thuế|\bmst\b|khấu trừ|hoàn thuế|quản lý thuế|nộp thuế',t,re.I):
        return ('thue','Thuế - Hóa đơn','regex-thue')
    if re.search(r'kế toán|ke toan|tài khoản|tai khoan|định khoản|dinh khoan|chứng từ|chung tu|sổ kế toán|bao cao tai chinh|báo cáo tài chính|chuẩn mực|chế độ kế toán|thông tư 200|thông tư 133|thông tư 99',t,re.I):
        return ('ke-toan','Kế toán','regex-ketoan')
    # fallback default for legal docs mostly tax-heavy in this corpus
    return ('thue','Thuế - Hóa đơn','fallback-thue')

mapped=[]
for a in rows:
