def fold(s):
    n=unicodedata.normalize('NFD',s or '')
    n=''.join(ch for ch in n if unicodedata.category(ch)!='Mn')
    return n.replace('đ','d').replace('Đ','D').lower()

def map_target(title,slug):
    t=fold((title or '')+' '+(slug or '').replace('-',' '))

    # 1) Career/learning
    if re.search(r'phong van|xin viec|tuyen\s*kt|tuyen\s*ke toan|kinh nghiem nghe', t):
        return ('tham-khao-hoc-lieu','Học liệu - Tham khảo','kinh-nghiem-hoi-dap-nghe-nghiep','Kinh nghiệm - Hỏi đáp - Nghề nghiệp','rule-nghenghiep')

    # 2) Labor & insurance
    if re.search(r'lao dong|tro cap|thuong luong tap the|doi thoai tai noi lam viec|nghi huu|thang bang luong|ca dem|mat viec|thoi viec|sinh con|duong suc|bhxh|bhyt|bhtn', t):
        if re.search(r'sinh con|duong suc|bhxh|bhyt|bhtn', t):
            return ('lao-dong-bao-hiem','Lao động - Bảo hiểm','bao-hiem','BHXH - BHYT - BHTN','rule-laodong-bh')
        return ('lao-dong-bao-hiem','Lao động - Bảo hiểm','lao-dong-tien-luong','Lao động - Tiền lương','rule-laodong-luong')

    # 3) Enterprise procedures
    if re.search(r'dang ky thanh lap chi nhanh|vpdd|van phong dai dien|dia diem kinh doanh|khuyen mai|hoi cho|trien lam|giai the|gop von|thay doi dia diem|thu tuc.*doanh nghiep|cong ty moi thanh lap', t):
        return ('doanh-nghiep-thu-tuc','Doanh nghiệp - Thủ tục','thu-tuc-doanh-nghiep','DN - Thủ tục','rule-dn-thutuc')

    # 4) Accounting operations / bookkeeping
    if re.search(r'chuyen so du|bao cao tinh hinh tai chinh|lap so|so chi tiet|so theo doi|so tien gui|kiem ke tai san|bang tong hop chi tiet vat lieu|uy quyen.*thanh toan|cong tac phi|ngoai te|tien vay', t):
        if re.search(r'bao cao tinh hinh tai chinh', t):
            return ('ke-toan','Kế toán','bao-cao-tai-chinh','Báo cáo tài chính','rule-ketoan-bctc')
        if re.search(r'kiem ke tai san|vat lieu|hang hoa|dung cu|kho', t):
            return ('ke-toan','Kế toán','tai-san-kho-ccdc','Tài sản - Kho - CCDC','rule-ketoan-kho')
        if re.search(r'chuyen so du', t):
            return ('ke-toan','Kế toán','chuan-muc-che-do-nguyen-tac','Chuẩn mực - Chế độ - Nguyên tắc','rule-ketoan-chedo')
        if re.search(r'thanh toan|tien vay|ngoai te', t):
            return ('ke-toan','Kế toán','tai-khoan-hach-toan','Tài khoản - Hạch toán','rule-ketoan-tk')
        return ('ke-toan','Kế toán','chung-tu-so-sach','Chứng từ - Sổ sách','rule-ketoan-sosach')

    # 5) Tax domain
    if re.search(r'thue|gtgt|tncn|tndn|khau tru|hoan thue|kiem tra thue|giay nop tien|nsnn|ho so thue|tron thue|gian lan thue|ca nhan cu tru', t):
        if re.search(r'tncn|ca nhan cu tru', t):
            return ('thue','Thuế - Hóa đơn','tncn','Thuế thu nhập cá nhân','rule-thue-tncn')
        if re.search(r'tndn', t):
            return ('thue','Thuế - Hóa đơn','tndn','Thuế thu nhập doanh nghiệp','rule-thue-tndn')
        if re.search(r'ho so.*khai thue ban dau|dang ky thue', t):
            return ('thue','Thuế - Hóa đơn','ma-so-thue-dang-ky-thue','Mã số thuế - Đăng ký thuế','rule-thue-mst')
        return ('thue','Thuế - Hóa đơn','gtgt-hoa-don','GTGT - Hóa đơn','rule-thue-gtgt')

    # fallback
    return ('ke-toan','Kế toán','chung-tu-so-sach','Chứng từ - Sổ sách','fallback-ketoan')

